import zipfile
OK_TAGS = ('py3', 'py313', 'cp313', 'py2.py3', 'cp39', 'cp310', 'cp311', 'cp312')
def _wheel_tag_ok(fname):
    segs = fname[:-4].split('-')
    tags = segs[-3:] if len(segs) >= 4 else segs[-2:]
    joined = '.'.join(tags)
    if 'any' in joined:
        return True
    return any(t in joined for t in OK_TAGS)

for whl in sorted(wheels_dir.glob('*.whl')):
    if not _wheel_tag_ok(whl.name):
        print(f'[setup]   [SKIP] {whl.name} — не подходит для Python '
              f'{sys.version_info.major}.{sys.version_info.minor}')
        continue

